#!/bin/sh
set -eu
umask 077
# Hex passwords are generated by configure-env.sh; reject config injection.
for value in "${REDIS_PASSWORD:?}" "${AUTH_REDIS_PASSWORD:?}"; do
  case "$value" in *[!0-9a-fA-F]*|'') echo 'Redis requires generated hex credentials' >&2; exit 1;; esac
  [ "${#value}" -ge 48 ] || exit 1
done
cat > /tmp/redis.conf <<EOF
appendonly yes
protected-mode yes
bind 0.0.0.0
user default off
user auth on >$AUTH_REDIS_PASSWORD ~rate:* ~2fa_challenge:* +ping +hello +auth +select +client|setinfo +client|setname +get +set +setex +del +incr +expire +ttl +eval
user broker on >$REDIS_PASSWORD ~private* ~scraping* ~celery* ~_kombu* ~unacked* ~*pidbox* &* +ping +hello +auth +time +select +client|setname +client|setinfo +get +mget +set +setex +psetex +exists +expire +pexpire +ttl +pttl +del +unlink +lpush +rpush +brpop +rpop +llen +lrange +lrem +ltrim +hset +hget +hmget +hgetall +hdel +hexists +hincrby +sadd +srem +smembers +sismember +zadd +zrem +zrange +zrevrangebyscore +zrangebyscore +zscore +zcard +zremrangebyscore +publish +subscribe +unsubscribe +psubscribe +punsubscribe +multi +exec +discard +watch +unwatch +evalsha +eval +script|load +script|exists
EOF
exec redis-server /tmp/redis.conf
